// Conceptual shard routing in Java
public class ShardRouter {
    private static final int SHARD_COUNT = 4;
    private final Map<Integer, DataSource> shards;

    // Hash-based shard key on userId
    public DataSource getShardForUser(long userId) {
        int shardId = (int) (userId % SHARD_COUNT);
        return shards.get(shardId);
    }

    // Range-based shard key on created_date
    // Shard 0: 2020, Shard 1: 2021, Shard 2: 2022, Shard 3: 2023+
    public DataSource getShardForOrder(LocalDate createdDate) {
        int year = createdDate.getYear();
        int shardId = Math.min(year - 2020, SHARD_COUNT - 1);
        return shards.get(shardId);
    }
}

// Spring AbstractRoutingDataSource for transparent shard routing
public class ShardingDataSource extends AbstractRoutingDataSource {
    @Override
    protected Object determineCurrentLookupKey() {
        // Set via ThreadLocal before each request
        return ShardContext.getCurrentShardId();
    }
}

// Anti-pattern: cross-shard join (avoid at all costs)
// SELECT * FROM shard1.orders o JOIN shard2.customers c ON o.customer_id = c.id
// Requires application-level join across multiple network calls
